#[path="../src/remaining_types/mapping_v1.rs"] mod mapping_v1;use mapping_v1::*;
fn fields()->Vec<Field>{vec![Field{source:"id".into(),target:"settlement_id".into(),required:true},Field{source:"player_id".into(),target:"player_id".into(),required:true},Field{source:"amount".into(),target:"amount".into(),required:true}]}
fn baseline()->(MappingDescriptor,MappingObservation){let descriptor=MappingDescriptor{source_contract_id:"SettlementRecord/v1".into(),target_contract_id:"SettlementResponse/v1".into(),direction:"forward".into(),correspondence:fields(),totality:"partial-fallible".into(),effect_policy:"none".into()};let observation=MappingObservation{source_contract_id:"SettlementRecord/v1".into(),target_contract_id:"SettlementResponse/v1".into(),direction:"forward".into(),observed_correspondence:fields(),missing_required_fields:vec![],undeclared_extra_fields:vec![],totality:"partial-fallible".into(),coercions:vec![],effect_policy:"none".into(),effects:vec![],failure_outcome:FailureOutcome{status:"failure".into(),code:Some("MAPPING_INPUT_INVALID".into()),details:vec!["missing:id".into()]}};(descriptor,observation)}
#[test]fn native_mapping_passes(){let(d,o)=baseline();assert_eq!(evaluate_mapping(&d,&o),Vec::<&str>::new());}
#[test]fn kills_all_ten_semantic_controls_as_singletons(){let(d,b)=baseline();let mut cases:Vec<(&str,MappingObservation)>=Vec::new();
 let mut v=b.clone();std::mem::swap(&mut v.source_contract_id,&mut v.target_contract_id);cases.push(("RMT_MAP_SOURCE_TARGET_SWAP",v));
 let mut v=b.clone();v.direction="reverse".into();cases.push(("RMT_MAP_DIRECTION_FLIP",v));let mut v=b.clone();v.missing_required_fields.push("id".into());cases.push(("RMT_MAP_MISSING_REQUIRED_FIELD",v));
 let mut v=b.clone();v.undeclared_extra_fields.push("debug".into());cases.push(("RMT_MAP_UNDECLARED_EXTRA_FIELD",v));let mut v=b.clone();v.observed_correspondence[0].target="id".into();cases.push(("RMT_MAP_CORRESPONDENCE_DRIFT",v));
 let mut v=b.clone();v.totality="total".into();cases.push(("RMT_MAP_TOTALITY_OVERCLAIM",v));let mut v=b.clone();v.coercions.push("amount:string-to-number".into());cases.push(("RMT_MAP_SILENT_COERCION",v));
 let mut v=b.clone();v.effects.push("network:undeclared".into());cases.push(("RMT_MAP_EFFECT_POLICY_VIOLATION",v));let mut v=b.clone();v.failure_outcome=FailureOutcome{status:"success".into(),code:None,details:vec![]};cases.push(("RMT_MAP_FAILURE_AS_SUCCESS",v));
 let mut v=b.clone();v.failure_outcome.details.clear();cases.push(("RMT_MAP_FAILURE_DETAIL_LOSS",v));assert_eq!(cases.len(),10);for(expected,observed)in cases{assert_eq!(evaluate_mapping(&d,&observed),vec![expected],"{expected}");}}
